    let output_commitments = [
        compute_commitment(above_u64, owner_pk, 333),
        compute_commitment(0, owner_pk, 444),
    ];

    main(
        spend_secret,
        [above_u64, 0],
        [111, 222],
        [0, 1],
        [path0, path1],
        [above_u64, 0],
        [owner_pk, owner_pk],
        [333, 444],
        0,
        555,
        root,
        nullifiers,
        output_commitments,
        compute_fee_commitment(0, 555),
        auth_pk_hash,
        0x9999,
    );
}

